public class StringUtils_join_TriageGen2Test {



    @Test
    public void testJoin_EmptyRange() {
        Object[] array = {"a", "b", "c"};
        // noOfItems = 0 - 0 = 0
        assertEquals("If noOfItems is 0, return empty string", "", StringUtils.join(array, ',', 0, 0));
        // noOfItems = 0 - 1 = -1
        assertEquals("If noOfItems is negative, return empty string", "", StringUtils.join(array, ',', 1, 0));
    }














}

