import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_join_TriageGen2Test {









    @Test
    public void testJoin_WithNullElements() {
        Object[] array = {"a", null, "c"};
        // The logic: if (array[i] != null) { buf.append(array[i]); }
        // For i=0: append 'a'
        // For i=1: i > 0, append separator ',', array[1] is null, nothing appended
        // For i=2: i > 1, append separator ',', append 'c'
        assertEquals("Null elements should be skipped but separators still applied", "a,,c", StringUtils.join(array, ',', 0, 3));
    }








}

